// Call the version function and perform a minimal sanity check on encoding.
unsigned long v = http_parser_version();
// The version should be non-zero and packed as MMMM mmmm pppp. Assert basic property.
FUZZ_ASSERT(v != 0, "http_parser_version returned 0");
// No persistent objects to output.

// Allocate a new parser object managed by the fuzzer pool and initialize it.
http_parser *parser = new http_parser();
// Choose a valid parser type from enum http_parser_type.
unsigned int t = *FUZZ_PARAM(unsigned int) % 3; // 0: HTTP_REQUEST, 1: HTTP_RESPONSE, 2: HTTP_BOTH
http_parser_init(parser, (http_parser_type)t);
// Track initialization and type for downstream stubs that require an initialized parser.
FUZZ_SET_ATTR_INT(parser, "inited", 1);
FUZZ_SET_ATTR_INT(parser, "type", (int)t);
FUZZ_SET_ATTR_INT(parser, "executed", 0);
FUZZ_SET_ATTR_INT(parser, "paused", 0);
// Provide parser as an output so it persists.

// Allocate settings and initialize to disable all callbacks by default.
http_parser_settings *settings = new http_parser_settings();
http_parser_settings_init(settings);
// Track initialization for downstream enforcement in execute.
FUZZ_SET_ATTR_INT(settings, "inited", 1);
// Provide settings as an output so it persists.

// Enforce that parser was initialized and settings have been prepared.
if (FUZZ_GET_ATTR_INT(parser, "inited") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(settings, "inited") != 1) { FUZZ_BAIL(); }
// Generate input buffer. Use string macro for arbitrary bytes; it's length-safe.
std::string data = FUZZ_PARAM_STR();
const char *buf = data.data();
size_t len = data.size();
// Execute the parser. Callbacks may all be NULL; this is allowed by API.
size_t nparsed = http_parser_execute(parser, settings, buf, len);
// Property: parsed byte count cannot exceed provided length.
FUZZ_ASSERT(nparsed <= len, "nparsed exceeds input length");
// Update execution count for downstream functions that require having parsed some data.
FUZZ_SET_ATTR_INT(parser, "executed", FUZZ_GET_ATTR_INT(parser, "executed") + 1);
// If parser encountered an error (nparsed < len and not upgrade), allow the fuzzer to continue; no constraint violation here.
// Return parser and settings to the pool as they remain valid and owned by the runtime.

// Must be called after sufficient progress (typically headers complete or message complete).
if (FUZZ_GET_ATTR_INT(parser, "executed") <= 0) { FUZZ_BAIL(); }
// Invoke the query function; result is advisory, no further constraints.
(void)http_should_keep_alive(parser);
// Return parser so it remains available.

// Provide a valid method enum value. Use the parser's observed method after execution.
if (FUZZ_GET_ATTR_INT(parser, "executed") <= 0) { FUZZ_BAIL(); }
// parser->method is defined only for requests; if this parser type isn't request-capable, bail to honor requirement for valid enumerator.
int ptype = FUZZ_GET_ATTR_INT(parser, "type");
if (ptype == (int)HTTP_RESPONSE) { FUZZ_BAIL(); }
// Cast the observed method to the enum type and call the function.
const char *mstr = http_method_str((http_method)parser->method);
// Basic property: should return a non-null pointer for valid enumerators.
FUZZ_ASSERT(mstr != nullptr, "http_method_str returned null");
// Return parser to pool.

// Use a valid error code sourced from the parser after an execute step.
if (FUZZ_GET_ATTR_INT(parser, "executed") <= 0) { FUZZ_BAIL(); }
const char *ename = http_errno_name((http_errno)parser->http_errno);
FUZZ_ASSERT(ename != nullptr, "http_errno_name returned null");
// Return parser to pool.

// Use a valid error code sourced from the parser after an execute step.
if (FUZZ_GET_ATTR_INT(parser, "executed") <= 0) { FUZZ_BAIL(); }
const char *edesc = http_errno_description((http_errno)parser->http_errno);
FUZZ_ASSERT(edesc != nullptr, "http_errno_description returned null");
// Return parser to pool.

// Allocate and initialize a URL parse result container.
http_parser_url *u = new http_parser_url();
http_parser_url_init(u);
// Track initialization state for downstream parse_url call.
FUZZ_SET_ATTR_INT(u, "inited", 1);
// Provide u back to pool.

// Enforce that the result container was initialized.
if (FUZZ_GET_ATTR_INT(u, "inited") != 1) { FUZZ_BAIL(); }
// Prepare input buffer and CONNECT flag.
std::string url = FUZZ_PARAM_STR();
int is_connect = ((int)(*FUZZ_PARAM(unsigned int) & 1));
// Call the parser; on failure, bail per error handling guidance.
int rc = http_parser_parse_url(url.data(), url.size(), is_connect, u);
if (rc != 0) { FUZZ_BAIL(); }
// On success, field_set indicates which UF_* fields are present; offsets are into the provided buffer.
// Return u so caller can reuse it.

// Enforce a valid, initialized parser.
if (FUZZ_GET_ATTR_INT(parser, "inited") != 1) { FUZZ_BAIL(); }
int paused = ((int)(*FUZZ_PARAM(unsigned int) & 1));
http_parser_pause(parser, paused);
FUZZ_SET_ATTR_INT(parser, "paused", paused != 0 ? 1 : 0);
// Return parser back to the pool.

// Should be called reflecting current parsing state; require at least one execute step.
if (FUZZ_GET_ATTR_INT(parser, "executed") <= 0) { FUZZ_BAIL(); }
(void)http_body_is_final(parser);
// No further constraints; return parser.

