import random
import string
from typing import List, Tuple

# URL generator for http_parser_parse_url
# Generates syntactically valid URLs covering many combinations of components.

_SCHEMES = [
    "http", "https", "ws", "wss", "ftp", "file"
]

# Common host labels and TLDs
_HOST_LABELS = [
    "www", "api", "m", "static", "cdn", "img", "v1", "x"
]
_TLDS = [
    "com", "org", "net", "io", "dev", "co", "example"
]

_PATH_SEGS = [
    "", "index", "home", "login", "search", "status", "about", "v1", "v2",
    "users", "items", "_hidden", "~user", "äö", "スペース"
]

_QUERY_KEYS = [
    "q", "page", "limit", "sort", "token", "redirect", "utm_source", "format", "debug"
]
_QUERY_VALUES = [
    "", "1", "10", "asc", "desc", "true", "false", "json", "xml", "A%20B", "äö", "スペース"
]

_FRAGMENTS = [
    "", "top", "bottom", "section-1", "Überschrift", "スペース"
]

_IPV4_SAMPLES = [
    "127.0.0.1", "192.168.0.1", "10.0.0.1", "8.8.8.8", "0.0.0.0"
]

# Some IPv6 samples, including zone-id and shorthand
_IPV6_SAMPLES = [
    "[::1]", "[2001:db8::1]", "[fe80::1%25eth0]", "[::ffff:192.0.2.128]", "[2001:db8:85a3::8a2e:370:7334]"
]

# Userinfo components
_USERNAMES = ["user", "admin", "alice", "bob", "äö", "スペース"]
_PASSWORDS = ["pass", "secret", "p@ss", "", "t%3Ast", "スペース"]

def _rand_choice(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(len(items))]

def _rand_bool(rng: random.Random, p: float = 0.5) -> bool:
    return rng.random() < p

def _gen_host(rng: random.Random) -> str:
    choice = rng.random()
    if choice < 0.25:
        # IPv4
        if _rand_bool(rng, 0.5):
            return _rand_choice(rng, _IPV4_SAMPLES)
        # random IPv4
        return ".".join(str(rng.randrange(0, 256)) for _ in range(4))
    elif choice < 0.45:
        # IPv6 literal
        return _rand_choice(rng, _IPV6_SAMPLES)
    else:
        # Registered name
        labels = []
        nlabels = rng.randint(1, 3)
        for i in range(nlabels):
            if _rand_bool(rng, 0.6):
                labels.append(_rand_choice(rng, _HOST_LABELS))
            else:
                # random label (letters, digits, hyphens)
                L = rng.randint(1, 10)
                chars = string.ascii_lowercase + string.digits + "-"
                # ensure not starting or ending with hyphen
                s = rng.choice(string.ascii_lowercase + string.digits)
                for _ in range(L - 2):
                    s += rng.choice(chars)
                if L > 1:
                    s += rng.choice(string.ascii_lowercase + string.digits)
                labels.append(s)
        tld = _rand_choice(rng, _TLDS)
        return ".".join(labels + [tld])

def _gen_port(rng: random.Random) -> str:
    # include common ports and random ones, sometimes 0 or 65535 boundary
    common = ["80", "443", "8080", "8000", "8443", "21", "0", "65535"]
    if _rand_bool(rng, 0.6):
        return _rand_choice(rng, common)
    return str(rng.randrange(0, 65536))

def _pct_enc(s: str) -> str:
    # Minimal percent-encoding for non-ASCII or space
    out = []
    for ch in s:
        o = ord(ch)
        if 0x21 <= o <= 0x7E and ch not in "% #?":
            out.append(ch)
        elif ch == " ":
            out.append("%20")
        else:
            # percent-encode utf-8 bytes
            for b in ch.encode("utf-8"):
                out.append("%" + format(b, "02X"))
    return "".join(out)

def _gen_path(rng: random.Random) -> str:
    # Decide between absolute-path, absolute-path with empty segments, or no path
    if _rand_bool(rng, 0.1):
        return ""  # no path (authority-only)
    segs = []
    n = rng.randint(0, 6)
    for i in range(n):
        seg = _rand_choice(rng, _PATH_SEGS)
        # allow mix of safe and encoded chars
        if _rand_bool(rng, 0.4):
            seg = _pct_enc(seg)
        # sometimes add matrix-like params or dot-segments
        if _rand_bool(rng, 0.2):
            seg += ";" + _pct_enc(_rand_choice(rng, ["v=1", "a=b", "lang=en", "ç=✓"]))
        if _rand_bool(rng, 0.1):
            seg = "." if _rand_bool(rng) else ".."
        segs.append(seg)
    leading_slash = True
    # occasionally multiple leading slashes (path-absolute-ambiguous cases)
    prefix = "/" * rng.randint(1, 3) if leading_slash else ""
    path = prefix + "/".join(segs)
    # sometimes ensure trailing slash
    if _rand_bool(rng, 0.3) and (path or prefix):
        if not path.endswith("/"):
            path += "/"
    return path

def _gen_query(rng: random.Random) -> str:
    if not _rand_bool(rng, 0.6):
        return ""
    parts: List[str] = []
    n = rng.randint(0, 6)
    for _ in range(n):
        k = _pct_enc(_rand_choice(rng, _QUERY_KEYS))
        v = _pct_enc(_rand_choice(rng, _QUERY_VALUES))
        if _rand_bool(rng, 0.2):
            parts.append(k)
        else:
            parts.append(f"{k}={v}")
    # also allow raw strings without key=value
    if _rand_bool(rng, 0.1):
        parts.append(_pct_enc("token:" + ''.join(rng.choice(string.ascii_letters) for _ in range(6))))
    return "?" + "&".join(parts)

def _gen_fragment(rng: random.Random) -> str:
    if not _rand_bool(rng, 0.4):
        return ""
    frag = _pct_enc(_rand_choice(rng, _FRAGMENTS))
    return "#" + frag

def _gen_userinfo(rng: random.Random) -> str:
    if not _rand_bool(rng, 0.35):
        return ""
    user = _pct_enc(_rand_choice(rng, _USERNAMES))
    pw = _rand_choice(rng, _PASSWORDS)
    if _rand_bool(rng, 0.5):
        userinfo = f"{user}:{_pct_enc(pw)}@"
    else:
        userinfo = f"{user}@"
    return userinfo

def _gen_authority(rng: random.Random) -> str:
    userinfo = _gen_userinfo(rng)
    host = _gen_host(rng)
    port = ":" + _gen_port(rng) if _rand_bool(rng, 0.5) else ""
    return userinfo + host + port

def _gen_absolute_uri(rng: random.Random) -> str:
    scheme = _rand_choice(rng, _SCHEMES)
    # Special-case file URI which may be file://host/path or file:///path
    if scheme == "file":
        if _rand_bool(rng, 0.5):
            authority = _gen_authority(rng)
            path = _gen_path(rng) or "/"
            return f"file://{authority}{path}{_gen_query(rng)}{_gen_fragment(rng)}"
        else:
            path = _gen_path(rng)
            if not path.startswith("/"):
                path = "/" + path
            if not path:
                path = "/"
            return f"file://{path}{_gen_query(rng)}{_gen_fragment(rng)}"
    # Normal authority-based URIs
    authority = _gen_authority(rng)
    path = _gen_path(rng)
    return f"{scheme}://{authority}{path}{_gen_query(rng)}{_gen_fragment(rng)}"

def _gen_authority_form(rng: random.Random) -> str:
    # For CONNECT: authority-form = host[:port]
    host = _gen_host(rng)
    port = ":" + _gen_port(rng) if _rand_bool(rng, 0.8) else ""
    return f"{host}{port}"

def _gen_origin_form(rng: random.Random) -> str:
    # Origin-form starts with "/" and may have query
    path = _gen_path(rng)
    if not path.startswith("/"):
        path = "/" + path
    return f"{path}{_gen_query(rng)}{_gen_fragment(rng)}"

def _gen_asterisk_form() -> str:
    return "*"

def _bounded_bytes(s: str) -> bytes:
    b = s.encode("utf-8")
    if len(b) > 4096:
        # Trim conservatively at component boundaries
        return b[:4096]
    return b

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose URL form types to exercise parser varieties:
    # - absolute-URI (scheme://authority path?query#frag)
    # - authority-form (for CONNECT)
    # - origin-form (path?query) and asterisk-form (*)
    choice = rng.random()
    if choice < 0.55:
        s = _gen_absolute_uri(rng)
    elif choice < 0.75:
        s = _gen_origin_form(rng)
    elif choice < 0.9:
        s = _gen_authority_form(rng)
    else:
        s = _gen_asterisk_form()
    return _bounded_bytes(s)
